-- cpd-migration: additive
-- The Plan's outline (contract §2.2 Plan `outline`, §4.5; hs-d502): the canonical JSON of what the Lead has settled with
-- the User, the source of a Plan review's summary. Null until `plan outline`; nothing is back-filled, so the fingerprint
-- of an existing Plan is unchanged. The history triggers of `plans` are regenerated by the runner's reconcile (K4).
ALTER TABLE plans ADD COLUMN outline TEXT CHECK (outline IS NULL OR (json_valid(outline) AND json_type(outline) = 'object'));
INSERT INTO event_kinds (name) VALUES ('plan-outlined');
